import hashlib,json,os,pathlib,re,statistics,subprocess,time
root=pathlib.Path.cwd();work=root/'_build/cache-capacity/cache-probe'
env={k:v for k,v in os.environ.items() if not k.startswith(('VIBE_','NODE_'))}
env.update(VIBE_PREOPEN_DIR=str(root),VIBE_IMPORT_ABI='raw',VIBE_WASM_MEMORY_STATS='1',VIBE_CHECKED_MODULE_CACHE='off',VIBE_EXPERIMENTAL_AST_CACHE='0',VIBE_WASM_NAMES='0')
rows=[];report={'protocol':'Three alternating AB/BA pairs, cold then warm in an isolated cache per compiler and pair; bump compiler runtime, RC output. Compiler probes compiled by the same seed from saved baseline and API compiler flat sources, counted production cache entry.','rows':rows}
for label in 'ab': report[label+'_compiler_sha256']=hashlib.sha256((work/(label+'.wasm')).read_bytes()).hexdigest()
for round in range(3):
 for side in ('ab' if round%2==0 else 'ba'):
  folder=work/f'r{round}-{side}';folder.mkdir(exist_ok=False)
  for temp in ['cold','warm']:
   out=folder/'out.wasm';t=time.monotonic()
   p=subprocess.run(['bash','scripts/run_wasm_vibe_host_runner.sh','--invoke','_start',str(work/(side+'.wasm')),str(work/'app/main.vibe'),str(out)],env={**env,'VIBE_BUILD_CACHE_DIR':str(folder/'cache')},capture_output=True,text=True,timeout=120)
   wall=time.monotonic()-t;(folder/(temp+'.log')).write_text(p.stdout+p.stderr);p.check_returncode();assert out.exists(),p.stdout+p.stderr
   row=dict(round=round,variant=side,temperature=temp,wall_s=wall,sha256=hashlib.sha256(out.read_bytes()).hexdigest(),wasm_bytes=out.stat().st_size)
   row.update({k:int(v) for k,v in re.findall(r'\b(offered|recompiled|allocated|heap_ptr|rss|pages|bytes)=(\d+)',p.stdout+p.stderr)})
   rows.append(row);(work/'report.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(row),flush=True)
for temp in ['cold','warm']:
 for key in ['wall_s','allocated','offered','recompiled','heap_ptr']:
  med={s:statistics.median(r[key] for r in rows if r['variant']==s and r['temperature']==temp) for s in 'ab'}
  print(temp,key,med,flush=True)

