import hashlib,json,os,pathlib,re,statistics,subprocess,time
root=pathlib.Path.cwd();work=root/'_build/cache-capacity/selfhost'
env={k:v for k,v in os.environ.items() if not k.startswith(('VIBE_','NODE_'))}
env.update(VIBE_PREOPEN_DIR=str(root),VIBE_IMPORT_ABI='raw',VIBE_FS_COMPILE='1',VIBE_BACKEND='wasi',VIBE_RC='1',VIBE_CHECKED_MODULE_CACHE='off',VIBE_EXPERIMENTAL_AST_CACHE='0',VIBE_CODEGEN_BODY_CACHE='off',VIBE_WASM_MEMORY_STATS='1',VIBE_WASM_NAMES='0')
rows=[];report={'baseline_source':'270687657 (capacity API and cache guards, before reservation use)','candidate_source':'bc8a6a373 (pruner output reservation)','protocol':'Three alternating AB/BA pairs per compiler runtime and corpus. Equal-length paths; fresh cache per pair/variant, cold then warm; same current input sources and RC output; checker/AST/body caches disabled, production module caches enabled; Node wrapper with inlining. No concurrent local build/test/measurement.','rows':rows,'compilers':{}}
for runtime in ['bump','rc']:
 for side in 'ab':
  path=work/f'{side}-{runtime}.wasm';report['compilers'][f'{side}-{runtime}']={'sha256':hashlib.sha256(path.read_bytes()).hexdigest(),'bytes':path.stat().st_size}
if (work/'report.json').exists():
 report=json.loads((work/'report.json').read_text());rows=report['rows']
for runtime in ['bump','rc']:
 for corpus,source,entry in [('closure','lib/@vibe/compiler/tests/codegen_lexer_test.vibe','__no_entry__'),('cli','lib/@vibe/cli/entry.vibe','cli_main')]:
  expected=None
  for round in range(3):
   for side in ('ab' if round%2==0 else 'ba'):
    folder=work/f'{runtime}-{corpus}-{round}-{side}';folder.mkdir(exist_ok=True)
    for temp in ['cold','warm']:
     prior=[r for r in rows if r['runtime']==runtime and r['corpus']==corpus and r['round']==round and r['variant']==side and r['temperature']==temp]
     if prior:
      if expected is None: expected=prior[0]['output_sha256']
      assert expected==prior[0]['output_sha256']
      continue
     out=folder/'out.wasm';t=time.monotonic()
     p=subprocess.run(['bash','scripts/run_wasm_vibe_host_runner.sh','--invoke','cli_main',str(work/f'{side}-{runtime}.wasm'),source,str(out),entry],env={**env,'VIBE_BUILD_CACHE_DIR':str(folder/'cache')},capture_output=True,text=True,timeout=180)
     elapsed=time.monotonic()-t;(folder/f'{temp}.log').write_text(p.stdout+p.stderr);p.check_returncode();assert out.exists(),p.stdout+p.stderr
     digest=hashlib.sha256(out.read_bytes()).hexdigest()
     if expected is None: expected=digest
     assert digest==expected, f'output mismatch {runtime} {corpus} {round} {side} {temp}'
     stats=re.findall(r'\[wasm-memory\][^\n]+',p.stderr)[-1]
     row=dict(runtime=runtime,corpus=corpus,round=round,variant=side,temperature=temp,wall_s=elapsed,output_bytes=out.stat().st_size,output_sha256=digest,**{k:int(v) for k,v in re.findall(r'(pages|bytes|heap_ptr|rss)=([0-9]+)',stats)})
     rows.append(row);(work/'report.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(row),flush=True)
for runtime in ['bump','rc']:
 for corpus in ['closure','cli']:
  for temp in ['cold','warm']:
   selected=[r for r in rows if r['runtime']==runtime and r['corpus']==corpus and r['temperature']==temp]
   summary={k:{s:statistics.median(r[k] for r in selected if r['variant']==s) for s in 'ab'} for k in ['wall_s','heap_ptr','rss','pages']}
   print(runtime,corpus,temp,json.dumps(summary),flush=True)

