env={k:v for k,v in os.environ.items() if not k.startswith(('VIBE_','NODE_'))}
env.update(VIBE_PREOPEN_DIR=str(root),VIBE_IMPORT_ABI='raw',VIBE_FS_COMPILE='1',VIBE_RC='1',VIBE_WASM_NAMES='0',VIBE_CHECKED_MODULE_CACHE='off',VIBE_EXPERIMENTAL_AST_CACHE='0',VIBE_CODEGEN_BODY_CACHE='off',VIBE_WASM_MEMORY_STATS='1')
rows=[]
for i in range(3):
 for s in ('ab' if i%2==0 else 'ba'):
  folder=work/f'{i}-{s}';folder.mkdir()
  for temp in ['cold','warm']:
   out=folder/'out.wasm';t=time.monotonic()
   p=subprocess.run(['bash','scripts/run_wasm_vibe_host_runner.sh','--invoke','cli_main',str(work/(s+'.wasm')),'lib/@vibe/cli/entry.vibe',str(out),'cli_main'],env={**env,'VIBE_BUILD_CACHE_DIR':str(folder/'cache')},capture_output=True,text=True,timeout=180)
   wall=time.monotonic()-t;(folder/f'{temp}.log').write_text(p.stdout+p.stderr);p.check_returncode();assert out.exists()
   row=dict(round=i,variant=s,temperature=temp,wall_s=wall,output_sha256=hashlib.sha256(out.read_bytes()).hexdigest(),**{k:int(v) for k,v in re.findall(r'\b(heap_ptr|rss|pages|bytes)=(\d+)',p.stderr)})
   rows.append(row);(work/'report.json').write_text(json.dumps({'compiler_sha256':hashlib.sha256((work/'a.wasm').read_bytes()).hexdigest(),'rows':rows},indent=2)+'\n');print(json.dumps(row),flush=True)
for temp in ['cold','warm']:
 ratios=[]
 for i in range(3):
  pair={r['variant']:r for r in rows if r['round']==i and r['temperature']==temp}
  assert pair['a']['heap_ptr']==pair['b']['heap_ptr']
  assert pair['a']['output_sha256']==pair['b']['output_sha256']
  ratios.append((pair['b']['wall_s']/pair['a']['wall_s']-1)*100)
 print(temp,ratios,statistics.median(ratios),flush=True)

